/* 秋の演出に使う絵（葉5枚・実5個） */

  const AUTUMN_ART={
    leaf:[
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,'
    ],
    nut:[
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,',
      'data:image/webp;base64,'
    ],
  };
  const autumnPics={leaf:[],nut:[]},
    autumnIdx=(p,kind)=>kind==='leaf'?(p.i+Math.floor(p.i/5))%5:Math.floor(p.i/5)%5;
  for(const k of ['leaf','nut'])AUTUMN_ART[k].forEach((src,n)=>{const im=new Image();im.onload=()=>{autumnPics[k][n]=im};im.src=src});
